// Parses a money string into whole cents. "1.50" is 150 cents.
export function parseAmount(text) {
  const m = /^\s*(-?)(\d+)(?:\.(\d{1,2}))?\s*$/.exec(String(text));
  if (!m) return null;
  const cents = Number(m[2]) * 100 + Number((m[3] || '0').padEnd(2, '0'));
  return m[1] === '-' ? -cents : cents;
}

