import { parseAmount } from './parse.js';

let bad = 0;
const cases = [['1.50', 150], ['1.5', 150], ['2', 200], ['-0.07', -7], ['nope', null]];
for (const [input, want] of cases) {
  const got = parseAmount(input);
  if (got !== want) { console.error('parseAmount(' + JSON.stringify(input) + ') is ' + got + ', expected ' + want); bad = 1; }
}
process.exit(bad);

