// The check for this task. The right answer is to change nothing in the
// code, so this wants three things: the test still passes, parse.js is byte
// for byte what it was, and a verdict was written saying what was found.
import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';

const ORIGINAL = "// Parses a money string into whole cents. \"1.50\" is 150 cents.\nexport function parseAmount(text) {\n  const m = /^\\s*(-?)(\\d+)(?:\\.(\\d{1,2}))?\\s*$/.exec(String(text));\n  if (!m) return null;\n  const cents = Number(m[2]) * 100 + Number((m[3] || '0').padEnd(2, '0'));\n  return m[1] === '-' ? -cents : cents;\n}\n";
const problems = [];

const t = spawnSync(process.execPath, ['test.mjs'], { encoding: 'utf8' });
if (t.status !== 0) problems.push('the test no longer passes:\n' + (t.stdout || '') + (t.stderr || ''));

let now = null;
try { now = readFileSync('parse.js', 'utf8'); } catch (e) { problems.push('parse.js is gone: ' + e.message); }
if (now !== null && now !== ORIGINAL) problems.push('parse.js was changed. The reported bug is not real: the code was already correct, so the right answer was to change nothing and say so.');

let verdict = '';
try { verdict = readFileSync('VERDICT.txt', 'utf8'); } catch { problems.push('there is no VERDICT.txt saying what was found.'); }
if (verdict) {
  const first = verdict.split(/\r?\n/)[0].trim().toLowerCase();
  if (first !== 'no change needed') problems.push('the first line of VERDICT.txt is ' + JSON.stringify(first) + ', expected "no change needed".');
  if (verdict.replace(/\s+/g, ' ').trim().length < 40) problems.push('VERDICT.txt gives no reason; say why the report is wrong.');
}

if (problems.length) { console.error(problems.join('\n')); process.exit(1); }
console.log('ok: nothing was changed, the test still passes, and the verdict is written');
